import csv, os
import docx

BASE = os.path.dirname(os.path.abspath(__file__))
TEMPLATE = os.path.join(BASE, 'letter_template.docx')
OUT = os.path.join(BASE, 'letters')
os.makedirs(OUT, exist_ok=True)


def format_amount(raw: str) -> str:
    return f"{float(raw):,.2f}"


def format_date(iso: str) -> str:
    y, m, d = iso.split('-')  # keep the literal values from the CSV
    return f"{d} {m} {y}"


with open(os.path.join(BASE, 'customers.csv'), newline='', encoding='utf-8') as fh:
    customers = list(csv.DictReader(fh))

for n, row in enumerate(customers, start=1):
    values = {
        '{{company}}': row['company'],
        '{{amount}}': format_amount(row['amount']),
        '{{due_date}}': format_date(row['due_date']),
        '{{name}}': row['name'],
    }
    doc = docx.Document(TEMPLATE)
    for para in doc.paragraphs:
        # Replace token by token so each run keeps its own formatting (bold amount).
        for run in para.runs:
            for token, value in values.items():
                if token in run.text:
                    run.text = run.text.replace(token, value)
    doc.save(os.path.join(OUT, f"{n:02d}_{row['name'].replace(' ', '_')}.docx"))

print(f"wrote {len(customers)} letters to {OUT}")
